# executes the code generated by LLM
# executes tests for validaton

import subprocess, sys, tempfile, os


def execute_code(code, timeout=10, cwd=None):
    """
    Execute generated Python code safely in a separate process.
    Returns output, error, and success status.
    """

    temp_file_path = None

    try:
        # Create a temporary Python file
        temp_dir = cwd if cwd else None

        with tempfile.NamedTemporaryFile(
            mode="w",
            suffix=".py",
            delete=False,
            encoding="utf-8",
            dir=temp_dir
        ) as temp_file:

            temp_file.write(code)
            temp_file_path = temp_file.name

        # Execute the temporary Python file
        result = subprocess.run(
            [sys.executable, temp_file_path],
            capture_output=True,
            text=True,
            timeout=timeout,
            cwd=cwd
            )

        # If return code is 0, execution succeeded
        if result.returncode == 0:
            return result.stdout, "", True

        # Program ran but produced an error
        return result.stdout, result.stderr, False

    except subprocess.TimeoutExpired:
        return "", "Execution timed out.", False

    except Exception as e:
        return "", str(e), False

    finally:
        # Delete the temporary file
        if temp_file_path and os.path.exists(temp_file_path):
            os.remove(temp_file_path)


def run_tests(project_path, timeout=30):
    try:
        result = subprocess.run(
            [sys.executable, "-m", "pytest", "-q"],
            cwd=project_path,
            capture_output=True,
            text=True,
            timeout=timeout
        )

        return {
            "success": result.returncode == 0,
            "stdout": result.stdout,
            "stderr": result.stderr,
            "returncode": result.returncode
        }

    except subprocess.TimeoutExpired:
        return {
            "success": False,
            "stdout": "",
            "stderr": "Tests timed out.",
            "returncode": -1
        }

    except Exception as e:
        return {
            "success": False,
            "stdout": "",
            "stderr": str(e),
            "returncode": -1
        }